namespace {

const unsigned char kPngSignature[] = {
    0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A};

// IHDR: 1x1 grayscale 8-bit.
const unsigned char kIhdr1x1[] = {0x00, 0x00, 0x00, 0x0D, 0x49, 0x48, 0x44,
    0x52, 0x00, 0x00, 0x00, 0x01, 0x00, 0x00, 0x00, 0x01, 0x08, 0x00, 0x00,
    0x00, 0x00, 0x3A, 0x7E, 0x9B, 0x55};

const unsigned char kIendChunk[] = {
    0x00, 0x00, 0x00, 0x00, 0x49, 0x45, 0x4E, 0x44, 0xAE, 0x42, 0x60, 0x82};

void append(std::vector<uint8_t> & out, const unsigned char * p, size_t n) {
  out.insert(out.end(), p, p + n);
}

#ifdef GIMG_TEST_DATA_PNG
/** Load a PNG reference file into a buffer. Returns true on success. */
bool load_png_file(const char * filename, std::vector<uint8_t> & out) {
  std::string path = std::string(GIMG_TEST_DATA_PNG) + "/" + filename;
  std::ifstream f(path, std::ios::binary | std::ios::ate);
  if (!f) {
    return false;
  }
  std::ifstream::pos_type size = f.tellg();
  if (size <= 0) {
    return false;
  }
  out.resize(static_cast<size_t>(size));
  f.seekg(0);
  if (!f.read(reinterpret_cast<char *>(out.data()), out.size())) {
    return false;
  }
  return true;
}
#endif

/** PNG eXIf chunk type (for meta_raw tag). */
static constexpr uint32_t kPngChunk_eXIf = 0x65584966u;

/** FNV-1a 64-bit offset basis and prime (for canonical pixel hash). */
static constexpr uint64_t kFnv1aOffsetBasis = 0xcbf29ce484222325ULL;
static constexpr uint64_t kFnv1aPrime = 0x100000001b3ULL;

/**
 * Compute canonical pixel hash of decoded raster: FNV-1a 64-bit over raw
 * pixel bytes, row-major top-down. Only the pixel data (width * bpp per row)
 * is hashed, not stride padding. Ensures decode is deterministic and
 * regression-free.
 */
uint64_t raster_pixel_hash(const GIMG_Raster * raster) {
  if (!raster) {
    return 0;
  }
  const GIMG_Pixel_Format * fmt = gimg_raster_format(raster);
  size_t bpp = gimg_raster_bytes_per_pixel(fmt);
  if (bpp == 0) {
    return 0;
  }
  uint32_t w = gimg_raster_width(raster);
  uint32_t h = gimg_raster_height(raster);
  size_t row_bytes = w * bpp;
  const unsigned char * pixels =
      static_cast<const unsigned char *>(gimg_raster_pixels_const(
          const_cast<GIMG_Raster *>(raster)));
  size_t stride = gimg_raster_stride_bytes(raster);
  if (!pixels || stride < row_bytes) {
    return 0;
  }
  uint64_t hval = kFnv1aOffsetBasis;
  for (uint32_t y = 0; y < h; y++) {
    const unsigned char * row = pixels + y * stride;
    for (size_t i = 0; i < row_bytes; i++) {
      hval ^= static_cast<uint64_t>(row[i]);
      hval *= kFnv1aPrime;
    }
  }
  return hval;
}

} // namespace

TEST(PngDecode, DecodeNoIdatReturnsFormat) {
  // Minimal PNG (signature + IHDR + IEND, no IDAT). Decode should fail.
  std::vector<uint8_t> buf;
  append(buf, kPngSignature, sizeof(kPngSignature));
  append(buf, kIhdr1x1, sizeof(kIhdr1x1));
  append(buf, kIendChunk, sizeof(kIendChunk));

  GIMG_Stream * s = nullptr;
  GIMG_Result r = gimg_stream_create_memory(buf.data(), buf.size(), &s);
  ASSERT_EQ(r, GIMG_OK);
  ASSERT_NE(s, nullptr);

  GIMG_Doc * doc = nullptr;
  r = gimg_doc_load(s, nullptr, nullptr, &doc);
  ASSERT_EQ(r, GIMG_OK);
  ASSERT_NE(doc, nullptr);

  GIMG_Item * item = gimg_doc_item(doc, 0);
  ASSERT_NE(item, nullptr);

  GIMG_Raster * raster = nullptr;
  r = gimg_item_decode(item, nullptr, &raster);
  EXPECT_EQ(r, GIMG_ERR_FORMAT) << "decode with no IDAT should return FORMAT";
  EXPECT_EQ(raster, nullptr);

  gimg_doc_destroy(doc);
  gimg_stream_destroy(s);
}

TEST(PngDecode, DecodeEmptyIdatReturnsCorrupt) {
  // Minimal PNG with IDAT that decompresses to 0 bytes (empty stored block).
  const unsigned char kIdatEmpty[] = {0x00, 0x00, 0x00, 0x05, 0x49, 0x44, 0x41,
      0x54, 0x01, 0x00, 0x00, 0xFF, 0xFF, 0xCF, 0xCA, 0x62, 0x86};
  std::vector<uint8_t> buf;
  append(buf, kPngSignature, sizeof(kPngSignature));
  append(buf, kIhdr1x1, sizeof(kIhdr1x1));
  append(buf, kIdatEmpty, sizeof(kIdatEmpty));
  append(buf, kIendChunk, sizeof(kIendChunk));

  GIMG_Stream * s = nullptr;
  gimg_stream_create_memory(buf.data(), buf.size(), &s);
  GIMG_Doc * doc = nullptr;
  GIMG_Result r = gimg_doc_load(s, nullptr, nullptr, &doc);
  ASSERT_EQ(r, GIMG_OK);
  ASSERT_NE(doc, nullptr);

  GIMG_Item * item = gimg_doc_item(doc, 0);
  GIMG_Raster * raster = nullptr;
  r = gimg_item_decode(item, nullptr, &raster);
  EXPECT_EQ(r, GIMG_ERR_CORRUPT) << "empty IDAT decompress should be corrupt";
  EXPECT_EQ(raster, nullptr);

  gimg_doc_destroy(doc);
  gimg_stream_destroy(s);
}

